const cfg = $('Config').first().json;
const num = (v) => { const n = Number(v); return isFinite(n) ? n : 0; };
const uniq = (rows, key) => { const seen = {}; const out = []; rows.forEach(r => { const k = String(r[key] || '').trim(); if (k && !seen[k]) { seen[k] = true; out.push(r); } }); return out; };
const cal = uniq($('Read Launch Calendar').all().map(i => i.json).filter(r => r && r.item_id), 'item_id');
const subs = uniq($('Read Subscribers').all().map(i => i.json).filter(r => r && r.sub_id), 'sub_id');
const logs = uniq($('Read Send Log').all().map(i => i.json).filter(r => r && r.log_id), 'log_id');
const dedupe = (String(cfg.dedupe_enabled) === 'true') || (cfg.dedupe_enabled === true);
const done = {};
logs.forEach(l => { done[String(l.item_id || '').trim()] = true; });
const TZ = num(cfg.tz_offset_minutes) || 330;
const pad = (n) => String(n).padStart(2, '0');
const now = new Date(Date.now() + TZ * 60000);
const fd = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
const today = fd(now);
const stamp = now.getUTCFullYear() + pad(now.getUTCMonth() + 1) + pad(now.getUTCDate()) + pad(now.getUTCHours()) + pad(now.getUTCMinutes());
const dueAll = cal.filter(c => String(c.scheduled_date || '').trim().slice(0, 10) <= today);
let skipped = 0;
const due = [];
dueAll.forEach(c => { if (dedupe && done[String(c.item_id).trim()]) { skipped += 1; return; } due.push(c); });
const active = subs.filter(s => String(s.status || '').toLowerCase().trim() === 'active' && String(s.email || '').trim());
const unsub = subs.length - active.length;
const cap = num(cfg.max_recipients) || 3;
const recips = active.slice(0, cap);
const upcoming = cal.filter(c => String(c.scheduled_date || '').trim().slice(0, 10) > today).slice(0, 4);
let upLines = '';
upcoming.forEach(u => { upLines += String(u.day_label || '') + ' | ' + String(u.channel || '') + ' | ' + String(u.subject || '') + '\n'; });
if (due.length === 0) { return [{ json: { nothing_due: true, today: today, stamp: stamp, skipped: skipped, total_items: cal.length, active_subs: active.length, unsub_count: unsub, upcoming: upcoming, upcoming_lines: upLines || 'none', brand_name: cfg.brand_name, owner_email: cfg.owner_email, owner_name: cfg.owner_name, store_url: cfg.store_url, email_items: [], social_items: [], sent_count: 0 } }]; }
const emailItems = due.filter(c => String(c.channel || '').toLowerCase().trim() === 'email');
const socialItems = due.filter(c => String(c.channel || '').toLowerCase().trim() !== 'email');
return [{ json: { nothing_due: false, today: today, stamp: stamp, skipped: skipped, total_items: cal.length,
  active_subs: active.length, unsub_count: unsub, recipients: recips, recipient_count: recips.length,
  email_items: emailItems, social_items: socialItems, due_count: due.length,
  upcoming: upcoming, upcoming_lines: upLines || 'none',
  brand_name: cfg.brand_name, owner_email: cfg.owner_email, owner_name: cfg.owner_name, store_url: cfg.store_url } }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const D = $('Today Engine').first().json;
if (D.nothing_due) { return []; }
const items = Array.isArray(D.email_items) ? D.email_items : [];
const recips = Array.isArray(D.recipients) ? D.recipients : [];
if (items.length === 0 || recips.length === 0) { return []; }
const NAVY = '#241A14', ESP = '#6F4E37', AMBER = '#C97B3C', CREAM = '#FBF7F0', WHITE = '#FFFFFF', INK = '#1A1A1A', GREY = '#6A6A6A';
const pad = (n) => String(n).padStart(2, '0');
const out = [];
let k = 0;
items.forEach(it => {
  const lines = String(it.body || '').split('\n').filter(l => l.trim());
  recips.forEach(r => {
    k += 1;
    let body = '';
    lines.forEach(l => { body += '<div style="font-size:15.5px;color:' + INK + ';line-height:1.65;margin-bottom:11px;">' + esc(l.trim()) + '</div>'; });
    const html = '<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="max-width:580px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
    '<tr><td style="background:' + NAVY + ';padding:20px 26px;"><div style="font-family:Georgia,serif;font-size:19px;font-weight:bold;color:' + WHITE + ';letter-spacing:1px;">' + esc(D.brand_name) + '</div></td></tr>' +
    '<tr><td style="padding:24px 26px 6px 26px;"><div style="font-size:16px;font-weight:bold;color:' + INK + ';margin-bottom:14px;">Hi ' + esc(r.name) + ',</div>' + body + '</td></tr>' +
    '<tr><td style="padding:6px 26px 22px 26px;"><a href="' + esc(D.store_url) + '" style="display:inline-block;background:' + AMBER + ';color:#FFFFFF;font-size:15px;font-weight:bold;text-decoration:none;padding:13px 30px;border-radius:7px;">Have a look</a></td></tr>' +
    '<tr><td style="padding:0 26px 20px 26px;"><div style="font-size:14px;color:' + INK + ';">Warmly,</div><div style="font-size:14px;color:' + INK + ';font-weight:bold;">' + esc(D.owner_name) + '</div><div style="font-size:13px;color:' + GREY + ';">' + esc(D.brand_name) + '</div></td></tr>' +
    '<tr><td style="background:' + CREAM + ';padding:12px 26px;"><div style="font-size:11px;color:' + GREY + ';">You are receiving this because you joined the ' + esc(r.segment) + ' list. Reply with the word stop and we will remove you.</div></td></tr>' +
    '</table></div>';
    out.push({ json: { to: String(r.email), subject: String(it.subject || ''), html: html, item_id: String(it.item_id), product_id: String(it.product_id), channel: 'email', day_label: String(it.day_label || ''), asset_type: String(it.asset_type || ''), recipient_name: String(r.name), seq: k } });
  });
});
return out;

const D = $('Today Engine').first().json;
if (D.nothing_due) { return []; }
const pad = (n) => String(n).padStart(2, '0');
const email = Array.isArray(D.email_items) ? D.email_items : [];
const social = Array.isArray(D.social_items) ? D.social_items : [];
const rc = Number(D.recipient_count) || 0;
const out = [];
let n = 0;
email.forEach(it => { n += 1; out.push({ json: { log_id: 'LG' + D.stamp + '-' + pad(n), run_date: D.today, item_id: String(it.item_id), product_id: String(it.product_id), channel: 'email', recipients: rc, status: 'sent' } }); });
social.forEach(it => { n += 1; out.push({ json: { log_id: 'LG' + D.stamp + '-' + pad(n), run_date: D.today, item_id: String(it.item_id), product_id: String(it.product_id), channel: String(it.channel), recipients: 0, status: 'owner_notified' } }); });
return out;

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const D = $('Today Engine').first().json;
const NAVY = '#241A14', ESP = '#6F4E37', AMBER = '#C97B3C', CREAM = '#FBF7F0', WHITE = '#FFFFFF', INK = '#1A1A1A', GREY = '#6A6A6A', GREEN = '#1B7E42';
const email = Array.isArray(D.email_items) ? D.email_items : [];
const social = Array.isArray(D.social_items) ? D.social_items : [];
const rc = Number(D.recipient_count) || 0;
let emHtml = '';
email.forEach(it => {
  emHtml += '<tr><td style="padding:0 26px 12px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E8DDD0;border-radius:8px;border-left:4px solid ' + GREEN + ';background:#FFFFFF;"><tr><td style="padding:13px 15px;">' +
  '<div style="font-size:11px;font-weight:bold;color:' + GREEN + ';letter-spacing:1px;">SENT &middot; ' + esc(it.day_label) + '</div>' +
  '<div style="font-family:Georgia,serif;font-size:17px;font-weight:bold;color:' + NAVY + ';margin-top:5px;">' + esc(it.subject) + '</div>' +
  '<div style="font-size:12.5px;color:' + GREY + ';margin-top:4px;">Delivered to ' + rc + ' subscriber(s)</div></td></tr></table></td></tr>';
});
let soHtml = '';
social.forEach(it => {
  let b = '';
  String(it.body || '').split('\n').filter(l => l.trim()).forEach(l => { b += '<div style="font-size:14px;color:#E8D5C4;line-height:1.6;margin-bottom:7px;">' + esc(l.trim()) + '</div>'; });
  soHtml += '<tr><td style="padding:0 26px 14px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="background:' + NAVY + ';border-radius:8px;"><tr><td style="padding:17px 19px;">' +
  '<div style="color:' + AMBER + ';font-size:11px;font-weight:bold;letter-spacing:1px;">POST THIS TODAY &middot; ' + esc(String(it.asset_type).replace(/_/g, ' ').toUpperCase()) + '</div>' +
  '<div style="color:#FFFFFF;font-family:Georgia,serif;font-size:15px;font-weight:bold;margin-top:6px;margin-bottom:10px;">' + esc(it.day_label) + '</div>' +
  '<div style="background:#3A2A1E;border-radius:6px;padding:14px 16px;">' + b + '</div></td></tr></table></td></tr>';
});
let upHtml = '';
(Array.isArray(D.upcoming) ? D.upcoming : []).forEach(u => {
  upHtml += '<tr><td style="padding:8px 12px;border-bottom:1px solid #E8DDD0;font-size:12.5px;color:' + INK + ';">' + esc(u.day_label) + '</td>' +
  '<td align="center" style="padding:8px 12px;border-bottom:1px solid #E8DDD0;"><span style="display:inline-block;background:' + (u.channel === 'email' ? ESP : AMBER) + ';color:#FFFFFF;font-size:10px;font-weight:bold;padding:3px 8px;border-radius:3px;">' + esc(String(u.channel).toUpperCase()) + '</span></td>' +
  '<td style="padding:8px 12px;border-bottom:1px solid #E8DDD0;font-size:12.5px;color:' + GREY + ';">' + esc(u.subject) + '</td></tr>';
});
const headline = D.nothing_due ? 'Nothing scheduled today' : (email.length + social.length) + ' launch action(s) today';
const sub = D.nothing_due ? ('Next up: ' + (D.upcoming.length ? String(D.upcoming[0].day_label) : 'nothing on the calendar')) : (email.length + ' email(s) sent, ' + social.length + ' post(s) for you to publish');
const html = '<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="max-width:660px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
'<tr><td style="background:' + NAVY + ';padding:24px 26px;"><div style="color:' + AMBER + ';font-size:11px;font-weight:bold;letter-spacing:3px;">LAUNCH DAY BRIEF</div>' +
'<div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:26px;font-weight:bold;margin-top:7px;">' + esc(headline) + '</div>' +
'<div style="color:#D8C4B0;font-size:13px;margin-top:5px;">' + esc(D.today) + ' &middot; ' + esc(sub) + '</div></td></tr>' +
'<tr><td style="padding:18px 26px 4px 26px;"><table width="100%" cellpadding="0" cellspacing="0"><tr>' +
'<td align="center" style="background:' + ESP + ';border-radius:6px;padding:14px 6px;"><div style="color:#FFFFFF;font-family:Georgia,serif;font-size:24px;font-weight:bold;">' + esc(email.length) + '</div><div style="color:#E8D5C4;font-size:10px;">emails sent</div></td><td width="7"></td>' +
'<td align="center" style="background:' + AMBER + ';border-radius:6px;padding:14px 6px;"><div style="color:#FFFFFF;font-family:Georgia,serif;font-size:24px;font-weight:bold;">' + esc(social.length) + '</div><div style="color:#F5E3D4;font-size:10px;">to post</div></td><td width="7"></td>' +
'<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:14px 6px;"><div style="color:' + NAVY + ';font-family:Georgia,serif;font-size:24px;font-weight:bold;">' + esc(D.active_subs) + '</div><div style="color:' + GREY + ';font-size:10px;">active list</div></td><td width="7"></td>' +
'<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:14px 6px;"><div style="color:' + NAVY + ';font-family:Georgia,serif;font-size:24px;font-weight:bold;">' + esc(D.skipped) + '</div><div style="color:' + GREY + ';font-size:10px;">already sent</div></td>' +
'</tr></table>' +
'<div style="font-size:11.5px;color:' + GREY + ';margin-top:8px;text-align:center;">' + esc(D.unsub_count) + ' unsubscribed contact(s) skipped &middot; ' + esc(D.total_items) + ' items on the calendar</div></td></tr>' +
(soHtml ? ('<tr><td style="padding:16px 26px 6px 26px;"><div style="font-family:Georgia,serif;font-size:17px;font-weight:bold;color:' + NAVY + ';">Your job today</div></td></tr>' + soHtml) : '') +
(emHtml ? ('<tr><td style="padding:12px 26px 6px 26px;"><div style="font-family:Georgia,serif;font-size:17px;font-weight:bold;color:' + NAVY + ';">Already handled for you</div></td></tr>' + emHtml) : '') +
(upHtml ? ('<tr><td style="padding:12px 26px 18px 26px;"><div style="font-family:Georgia,serif;font-size:16px;font-weight:bold;color:' + NAVY + ';margin-bottom:8px;">Coming up</div><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E8DDD0;border-radius:8px;">' + upHtml + '</table></td></tr>') : '') +
'<tr><td style="background:' + NAVY + ';padding:12px 26px;"><div style="color:#9A8878;font-size:11px;">' + esc(D.brand_name) + ' &middot; Product Launch Desk &middot; nothing is ever sent twice &middot; Powered by Haus of Intelligence</div></td></tr>' +
'</table></div>';
return [{ json: { brief_html: html, headline: headline, today: D.today, owner_email: D.owner_email, email_count: email.length, social_count: social.length } }];
